  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Why a restore was refused. The row is left untouched in every case. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: RestoreRefusalReason) {
    super(`Restore refused: ${reason}.`);
    this.name = "RestoreRefusedError";
  }
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Instant at which an archive becomes unrestorable. The sweep and `restoreIssue`
 * share this cut-off: an issue archived at exactly this instant is expired.
 */
export function retentionCutoff(retentionDays: number, now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

