export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const watermark = db
    .select({ highWater: issueNumberWatermarks.highWater })
    .from(issueNumberWatermarks)
    .where(eq(issueNumberWatermarks.projectId, projectId))
    .get();
  return Math.max(row?.value ?? 0, watermark?.highWater ?? 0) + 1;
}

/** Every archived issue in the workspace, with no page cap. */
export async function listArchivedIssues(
  orgId: OrgId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), isNotNull(issues.archivedAt)),
    )
    .all();
  return rows.map((row) => toIssue(row));
}

export type PurgedIssue = {
  readonly commentIds: readonly CommentId[];
  readonly attachmentBytes: readonly number[];
};

/**
 * Drops an issue and the rows that belong only to it. The project's high-water
 * issue number is raised first, so the purged number is never issued again.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  const db = getDb();
  const issue = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();
  if (!issue) return null;

  const commentRows = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .all();
  const attachmentRows = db
    .select({ sizeBytes: attachments.sizeBytes })
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .all();

  const existing = db
    .select({ highWater: issueNumberWatermarks.highWater })
    .from(issueNumberWatermarks)
    .where(eq(issueNumberWatermarks.projectId, issue.projectId))
    .get();
  const highWater = Math.max(existing?.highWater ?? 0, issue.number);
  if (existing) {
    db.update(issueNumberWatermarks)
      .set({ highWater })
      .where(eq(issueNumberWatermarks.projectId, issue.projectId))
      .run();
  } else {
    db.insert(issueNumberWatermarks)
      .values({ projectId: issue.projectId, orgId, highWater })
      .run();
  }

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issueId),
      ),
    )
    .run();
  db.delete(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .run();
  db.delete(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .run();
  db.delete(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .run();

  return {
    commentIds: commentRows.map((row) => row.id as CommentId),
    attachmentBytes: attachmentRows.map((row) => row.sizeBytes),
  };
}

