/**
 * The retention sweep. Archived issues stay restorable until
 * `retentionDays × 24h` has passed, then they are deleted for good: the issue,
 * its label links, comments and attachments, plus both issue and comment
 * search documents. Attachment storage is given back per file, rounded up to
 * whole megabytes. The issues-used counter is left alone — archived issues
 * are not in it. Audit rows past the same window are purged as before.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
