      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = retentionCutoff(retentionDays, now);

      const archived = await issueRepo.listArchivedIssues(orgId);

      for (const issue of archived) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        const purged = await issueRepo.purgeIssue(orgId, issue.id);
        if (!purged) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        for (const commentId of purged.commentIds) {
          await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
        }

        const storageMb = purged.attachmentBytes.reduce(
          (sum, sizeBytes) => sum + Math.ceil(sizeBytes / BYTES_PER_MB),
          0,
        );
        if (storageMb > 0) {
          await usageRepo.incrementUsage(orgId, { storageMbUsed: -storageMb });
        }

        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
